package main

import "encoding/base64"

// indexHTML 内嵌的前端页面，由 frontend/index.html 经 gen_frontend.py 自动生成，请勿手改。
var indexHTML = func() []byte {
	const enc = ""
	b, err := base64.StdEncoding.DecodeString(enc)
	if err != nil {
		panic("index.html base64 解码失败: " + err.Error())
	}
	return b
}()
